{
    std::vector<std::string> scores = {"F", "D", "C", "B", "A", "A++"};
    std::string lettergrade;
    int grade;

    while (std::cin >> grade) {
        lettergrade = (grade < 60) ? scores[0] 
                                   : (grade == 100) ? scores[(grade - 50) / 10]
                                   : (grade % 10 > 7) ? scores[(grade - 50) / 10] + '+'
                                   : (grade % 10 < 3) ? scores[(grade - 50) / 10] + '-'
                                   : scores[(grade - 50) / 10];
        std::cout << lettergrade + '\n';
    }
    return 0;
}

